// UIntToUInt8 converts the value; a value out of range returns ErrOutOfRange and 0.
func UIntToUInt8(typed_value uint) (result uint8, err error) {
    if typed_value <= uint(MaxUInt8) {
        result = uint8(typed_value)
    } else {
        err = castError(typed_value, MinUInt8, MaxUInt8)
    }
    return
}

